let src = {};
try { src = $('Route By Type').item.json || {}; } catch (e) { src = {}; }
const j = $json;
return { json: {
  source_id: src.id || '',
  source_name: src.name || '',
  source_type: src.type || 'rss',
  title: j.title || '',
  url: j.link || j.url || j.guid || '',
  content: j.content || j['content:encoded'] || j.contentSnippet || '',
  summary: j.contentSnippet || j.summary || j.description || '',
  published_at: j.isoDate || j.pubDate || null,
  fetched_at: new Date().toISOString()
} };

const sources = $('Load Sources').all().map(i => i.json).filter(s => s.type === 'json');
const responses = $input.all();
const out = [];
responses.forEach((r, i) => {
  const src = sources[i] || {};
  const body = (r && r.json) ? r.json : {};
  let list = [];
  if (Array.isArray(body)) list = body;
  else list = body.items || body.articles || body.results || body.data || body.entries || [];
  if ((!Array.isArray(list) || list.length === 0) && (body.title || body.headline)) list = [body];
  (Array.isArray(list) ? list : []).forEach(a => {
    out.push({ json: {
      source_id: src.id || '',
      source_name: src.name || '',
      source_type: 'json',
      title: a.title || a.headline || a.name || '',
      url: a.url || a.link || a.href || src.url || '',
      content: a.content || a.body || a.description || a.summary || '',
      summary: a.summary || a.description || a.abstract || '',
      published_at: a.published_at || a.publishedAt || a.date || a.pubDate || null,
      fetched_at: new Date().toISOString()
    } });
  });
});
return out;

const sources = $('Load Sources').all().map(i => i.json).filter(s => s.type === 'html');
const responses = $input.all();
const kw = /news|article|press|release|directive|airworthiness|\bad\b|safety|notice|bulletin|report|incident|advisory|alert/i;
const skip = /\/(about|contact|privacy|terms|login|register|cookie|sitemap)\b/i;
const MAX = 15;
const out = [];
responses.forEach((r, i) => {
  const src = sources[i] || {};
  const j = (r && r.json) ? r.json : {};
  const titles = Array.isArray(j.titles) ? j.titles : (j.titles ? [j.titles] : []);
  const links = Array.isArray(j.links) ? j.links : (j.links ? [j.links] : []);
  const seen = new Set();
  let count = 0;
  let origin = ''; let base = String(src.url || '');
  const m = base.match(/^(https?:\/\/[^\/]+)/i); if (m) origin = m[1];
  const baseNoQuery = base.replace(/[?#].*$/, '').replace(/\/[^\/]*$/, '/');
  titles.forEach((t, idx) => {
    if (count >= MAX) return;
    const anchor = String(t || '').trim();
    let link = String(links[idx] || '').trim();
    if (!link) return;
    if (link.indexOf('http') !== 0) {
      if (link.indexOf('//') === 0) { link = 'https:' + link; }
      else if (link.indexOf('/') === 0) { link = origin + link; }
      else if (link.indexOf('#') === 0 || link.indexOf('mailto:') === 0 || link.indexOf('javascript:') === 0) { return; }
      else { link = baseNoQuery + link; }
    }
    if (link.indexOf('http') !== 0) return;
    if (skip.test(link)) return;
    const hay = (anchor + ' ' + link).toLowerCase();
    if (!kw.test(hay)) return;
    if (seen.has(link)) return;
    seen.add(link); count++;
    out.push({ json: { source_id: src.id || '', source_name: src.name || '', source_url: src.url || '', sub_url: link, anchor_text: anchor } });
  });
});
return out;

const j = $json;
const parts = [j.h1, j.page_title, j.body_text].filter(Boolean).join('\n');
return { json: { page_text: String(parts || '').slice(0, 15000) } };

let src = {};
try { src = $('Pick Subpages').item.json || {}; } catch(e) {}

// Classify & Extract node'undan gelen GPT sonucu
const cls = $json.classification || {};

// Ham body_text'i de al (tam içerik)
let fullContent = '';
try { fullContent = $('Extract Content').item.json.body_text || ''; } catch(e) {}

return { json: {
  source_id:   src.source_id || '',
  source_name: src.source_name || '',
  source_type: 'html',
  title:       cls.title || src.anchor_text || '',
  url:         src.sub_url || '',
  content:     String(fullContent || cls.summary || '').slice(0, 20000),
  summary:     cls.summary || '',
  category:    cls.category || 'General',
  severity:    cls.severity || 'INFO',
  tags:        cls.tags || [],
  classification_reasoning: cls.reasoning || '',
  published_at: (cls.published_at && String(cls.published_at).trim()) ? cls.published_at : null,
  fetched_at:  new Date().toISOString()
} };

function norm(s){ return String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim(); }
function normUrl(u){ return String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/[?#].*$/,'').replace(/\/$/,''); }
function hash(str){ let h=5381; for(let i=0;i<str.length;i++){ h=((h<<5)+h)+str.charCodeAt(i); h=h&0xffff; } return (h>>>0).toString(16); }
const j = $json;
const tn = norm(j.title);
const ch = hash(tn + '|' + normUrl(j.url));
// Keep existing category from HTML GPT path; others will be overwritten by LLM Classify
return { json: Object.assign({}, j, {
  title_normalized: tn,
  content_hash: ch,
  category: j.category || 'General',
  severity: j.severity || 'INFO',
  tags: j.tags || []
}) };

const existing = $input.all().map(i => i.json).filter(e => e && e.content_hash);
const existingHashes = new Set(existing.map(e => e.content_hash));
const existingUrls = new Set(existing.map(e => String(e.url || '').toLowerCase()));
const candidates = $('Add Hash').all().map(i => i.json);
const seen = new Set();
const out = [];
candidates.forEach(c => {
  if (existingHashes.has(c.content_hash)) return;
  if (existingUrls.has(String(c.url || '').toLowerCase())) return;
  if (seen.has(c.content_hash)) return;
  seen.add(c.content_hash);
  out.push({ json: c });
});
return out;

function cos(a,b){ if(!a||!b||!a.length||a.length!==b.length) return 0; let d=0,na=0,nb=0; for(let i=0;i<a.length;i++){ d+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; } if(!na||!nb) return 0; return d/(Math.sqrt(na)*Math.sqrt(nb)); }
const cands = $('Hash Dedup').all().map(i => i.json);
const resp = $input.all();
const items = cands.map((c, i) => {
  const r = resp[i] && resp[i].json ? resp[i].json : {};
  const e = r.data && r.data[0] ? r.data[0].embedding : null;
  return Object.assign({}, c, { embedding: Array.isArray(e) ? e : null });
});
const existing = $('MongoDB Find Existing').all().map(i => i.json).filter(e => e && Array.isArray(e.embedding));
const TH = 0.9;
const kept = [];
items.forEach(it => {
  it.dedup_group_id = it.content_hash;
  if (!it.embedding) { kept.push(it); return; }
  let dup = false;
  for (const e of existing) { if (cos(it.embedding, e.embedding) >= TH) { dup = true; it.dedup_group_id = e.dedup_group_id || e.content_hash; break; } }
  if (dup) return;
  for (const k of kept) { if (Array.isArray(k.embedding) && cos(it.embedding, k.embedding) >= TH) { dup = true; it.dedup_group_id = k.dedup_group_id; break; } }
  if (dup) return;
  kept.push(it);
});
return kept.map(k => ({ json: k }));

// Parse the LLM response and apply the classification to the original item.
// Preserves the exact output contract of the original Classify & Extract node.
const resp = $json || {};

// The HTTP Request node replaced $json with the API response, so recover the
// original item (and strip the internal _messages payload).
let j = {};
try { j = $('Build Prompt').item.json || {}; } catch(e) {}
const { _messages, ...item } = j;

let classification = {
  is_relevant: false, title: '', summary: '',
  published_at: '', category: 'General',
  severity: 'INFO', tags: [], reasoning: ''
};

try {
  const raw = resp.choices[0].message.content;
  classification = JSON.parse(raw);
} catch(e) {
  classification.reasoning = 'GPT hatasi: ' + String(e).slice(0, 100);
}

// is_relevant false ise bos dondur - sonraki node'lar bunu atlayacak
if (!classification.is_relevant) return null;

return { json: { ...item, classification } };
